const interactionMap = {
	"": "",
	hover: "-hover",
	active: "-active",
	press: "-press",
	focus: "-focus",
	disabled: "-disabled",
	highlight: "-highlight",
};
const usageMap = {
	"": "",
	background: "-bg",
	bg: "-bg",
	text: "-text",
	border: "-border",
	"contrast-text": "-contrast-text",
	"vivid-text": "-vivid-text",
	"vivid-bg": "-vivid-bg",
};
export const color = (
	sentiment: any,
	usage?: any,
	prominence?: any,
	interaction?: any,
) => {
	let _interaction = interactionMap[interaction || ""];
	let _usage = usageMap[usage || ""];
	if (typeof interaction === "object") {
		for (const [key, value] of Object.entries(interaction)) {
			_interaction = interactionMap[value ? key : ""];
		}
	}
	if (typeof usage === "object") {
		for (const [key, value] of Object.entries(usage)) {
			_usage = usageMap[value ? key : ""];
		}
	}

	const _prominence = prominence ? `-${prominence}` : "";

	if (_prominence === "dark") {
		return `var(--hbr-color-${sentiment}${_prominence})`;
	}
	return `var(--hbr-color-${sentiment}${_usage}${_prominence}${_interaction})`;
};
